  589: static void *velawear_imu_thread(void *context)
  590: {
  591:   velawear_agent_t *agent = (velawear_agent_t *)context;
  592:   bool fall_reported = false;
  593:   int last_motion_type = -1;
  594: 
  595:   while (agent->running)
  596:     {
  597:       imu_data_t sample;
  598:       motion_state_t motion;
  599:       velawear_event_t event;
  600:       int period_us = 20000;
  601: 
  602:       if (imu_sensor_read(&agent->imu, &sample) == VELAWEAR_OK)
  603:         {
  604:           int motion_type;
  605: 
  606:           motion = imu_sensor_get_motion_state(&agent->imu);
  607:           motion_type = motion.is_running ? 2 :
  608:                         (motion.is_moving ? 1 : 0);
  609: 
  610:           memset(&event, 0, sizeof(event));
  611:           event.type = VELAWEAR_EVENT_MOTION;
  612:           event.priority = VELAWEAR_PRIORITY_NORMAL;
  613:           event.timestamp = sample.timestamp;
  614:           event.data.motion.motion_type = motion_type;
  615:           event.data.motion.intensity = motion.motion_intensity;
  616: 
  617:           if (motion_type != last_motion_type)
  618:             {
  619:               const char *motion_name = motion_type == 2 ? "跑步" :
  620:                                         (motion_type == 1 ? "活动" : "静止");
  621:               syslog(LOG_INFO, "[MVP] IMU state=%s intensity=%.2f\n",
  622:                      motion_name, motion.motion_intensity);
  623:               velawear_ble_update_motion(motion_type,
  624:                                          motion.motion_intensity);
  625:               /* 活动恢复时清除 BLE 告警状态。 */
  626:               if (last_motion_type == 0 && motion_type != 0)
  627:                 {
  628:                   velawear_ble_set_alert(false);
  629:                 }
  630:               last_motion_type = motion_type;
  631:             }
  632: 
  633:           if (event_manager_push(&agent->events, &event) < 0)
  634:             {
  635:               syslog(LOG_WARNING,
  636:                      "[VelaWear] Failed to queue motion event\n");
  637:             }
  638: 
  639:           if (motion.fall_detected && !fall_reported)
  640:             {
  641:               event.type = VELAWEAR_EVENT_FALL;
  642:               event.priority = VELAWEAR_PRIORITY_CRITICAL;
  643:               if (event_manager_push(&agent->events, &event) < 0)
  644:                 {
  645:                   syslog(LOG_WARNING,
  646:                          "[VelaWear] Failed to queue fall event\n");
  647:                 }
  648:               fall_reported = true;
  649:             }
  650:           else if (!motion.fall_detected)
  651:             {
  652:               fall_reported = false;
  653:             }
  654:         }
  655: 
  656:       if (agent->config.imu_sample_rate_hz > 0)
  657:         {
  658:           period_us = 1000000 / agent->config.imu_sample_rate_hz;
  659:           if (period_us < 1000)
  660:             {
  661:               period_us = 1000;
  662:             }
  663:         }
  664: 
  665:       usleep(period_us);
