 105: int event_manager_init(velawear_events_t *events)
 106: {
 107:   struct mq_attr attr;
 108:   int ret;
 109: 
 110:   if (events == NULL)
 111:     {
 112:       return VELAWEAR_ERR_INVAL;
 113:     }
 114: 
 115:   memset(events, 0, sizeof(velawear_events_t));
 116:   events->queue = (mqd_t)-1;
 117: 
 118:   /* Initialize mutex */
 119: 
 120:   ret = pthread_mutex_init(&events->lock, NULL);
 121:   if (ret != 0)
 122:     {
 123:       return VELAWEAR_ERR_IO;
 124:     }
 125: 
 126:   ret = pthread_mutex_init(&events->pool_lock, NULL);
 127:   if (ret != 0)
 128:     {
 129:       pthread_mutex_destroy(&events->lock);
 130:       return VELAWEAR_ERR_IO;
 131:     }
 132: 
 133:   /* Create message queue */
 134: 
 135:   attr.mq_flags = 0;
 136:   attr.mq_maxmsg = EVENT_QUEUE_SIZE;
 137:   /* Keep the mqueue payload within CONFIG_MQ_MAXMSGSIZE.  Events are
 138:    * copied through heap-backed pointers so the full event union can
 139:    * remain available to handlers. */
 140:   attr.mq_msgsize = sizeof(uintptr_t);
 141:   attr.mq_curmsgs = 0;
 142: 
 143:   /* A crashed instance may leave pointer messages behind.  Remove the
 144:    * old queue before creating a fresh one for this process. */
 145:   mq_unlink("/velawear_events");
 146: 
 147:   events->queue = mq_open("/velawear_events", O_CREAT | O_RDWR, 0644,
 148:                           &attr);
 149:   if (events->queue == (mqd_t)-1)
 150:     {
 151:       syslog(LOG_ERR, "[EventMgr] Failed to create message queue: %d\n",
 152:              errno);
 153:       pthread_mutex_destroy(&events->pool_lock);
 154:       pthread_mutex_destroy(&events->lock);
 155:       return VELAWEAR_ERR_IO;
 156:     }
 157: 
 158:   events->running = false;
 159:   events->handler_count = 0;
 160: 
 161:   syslog(LOG_INFO, "[EventMgr] Initialized\n");
 162:   return VELAWEAR_OK;
 163: }
 164: 
 165: int event_manager_start(velawear_events_t *events)
 166: {
 167:   int ret;
 168: 
 169:   if (events->running)
 170:     {
 171:       return VELAWEAR_ERR_BUSY;
 172:     }
 173: 
 174:   events->running = true;
 175: 
 176:   ret = pthread_create(&events->thread, NULL, event_manager_thread, events);
 177:   if (ret != 0)
 178:     {
 179:       syslog(LOG_ERR, "[EventMgr] Failed to create thread: %d\n", ret);
 180:       events->running = false;
 181:       return VELAWEAR_ERR_IO;
 182:     }
 183: 
 184:   syslog(LOG_INFO, "[EventMgr] Started\n");
 185:   return VELAWEAR_OK;
 186: }
 187: 
 188: void event_manager_cleanup(velawear_events_t *events)
 189: {
 190:   if (events == NULL)
 191:     {
 192:       return;
 193:     }
 194: 
 195:   if (events->running)
 196:     {
 197:       events->running = false;
 198:       pthread_join(events->thread, NULL);
 199:     }
 200: 
 201:   if (events->queue != (mqd_t)-1)
 202:     {
 203:       mq_close(events->queue);
 204:       mq_unlink("/velawear_events");
 205:     }
 206: 
 207:   pthread_mutex_destroy(&events->pool_lock);
 208:   pthread_mutex_destroy(&events->lock);
 209: 
 210:   syslog(LOG_INFO, "[EventMgr] Cleaned up\n");
 211: }
