 213: int event_manager_push(velawear_events_t *events, velawear_event_t *event)
 214: {
 215:   uintptr_t message;
 216:   int slot = -1;
 217:   int ret;
 218: 
 219:   if (events == NULL || events->queue == (mqd_t)-1 || event == NULL)
 220:     {
 221:       return VELAWEAR_ERR_IO;
 222:     }
 223: 
 224:   pthread_mutex_lock(&events->pool_lock);
 225:   for (int i = 0; i < EVENT_POOL_SIZE; i++)
 226:     {
 227:       if (!events->pool_used[i])
 228:         {
 229:           slot = i;
 230:           events->pool_used[i] = true;
 231:           memcpy(&events->pool[i], event, sizeof(*event));
 232:           break;
 233:         }
 234:     }
 235:   pthread_mutex_unlock(&events->pool_lock);
 236: 
 237:   if (slot < 0)
 238:     {
 239:       return VELAWEAR_ERR_NOMEM;
 240:     }
 241: 
 242:   /* The queue carries a stable pool slot, not a heap pointer. */
 243:   message = (uintptr_t)(slot + 1);
 244:   ret = mq_send(events->queue, (const char *)&message,
 245:                 sizeof(message), event->priority);
 246:   if (ret < 0)
 247:     {
 248:       pthread_mutex_lock(&events->pool_lock);
 249:       events->pool_used[slot] = false;
 250:       pthread_mutex_unlock(&events->pool_lock);
 251:       syslog(LOG_WARNING, "[EventMgr] Failed to push event: %d\n", errno);
 252:       return VELAWEAR_ERR_IO;
 253:     }
 254: 
 255:   return VELAWEAR_OK;
 256: }
