 290: int decision_engine_init(velawear_engine_t *engine, velawear_config_t *config)
 291: {
 292:   memset(engine, 0, sizeof(velawear_engine_t));
 293: 
 294:   pthread_mutex_init(&engine->lock, NULL);
 295:   engine->config = config;
 296:   engine->running = false;
 297: 
 298:   /* Register hardcoded emergency rules */
 299: 
 300:   decision_engine_add_rule(engine, "fall_detected", 0,
 301:                            VELAWEAR_PRIORITY_CRITICAL,
 302:                            fall_detected_condition,
 303:                            fall_detected_action, engine);
 304: 
 305:   decision_engine_add_rule(engine, "heart_rate_critical", 0,
 306:                            VELAWEAR_PRIORITY_CRITICAL,
 307:                            heart_rate_critical_condition,
 308:                            heart_rate_critical_action, NULL);
 309: 
 310:   decision_engine_add_rule(engine, "battery_critical", 0,
 311:                            VELAWEAR_PRIORITY_HIGH,
 312:                            battery_critical_condition,
 313:                            battery_critical_action, NULL);
 314: 
 315:   decision_engine_add_rule(engine, "sedentary_reminder", 1,
 316:                            VELAWEAR_PRIORITY_NORMAL,
 317:                            sedentary_condition,
 318:                            sedentary_action, engine);
 319: 
 320:   syslog(LOG_INFO, "[Decision] Initialized with %d rules\n",
 321:          engine->rule_count);
 322:   return VELAWEAR_OK;
 323: }
 324: 
 325: int decision_engine_start(velawear_engine_t *engine)
 326: {
 327:   int ret;
 328: 
 329:   if (engine->running)
 330:     {
 331:       return VELAWEAR_ERR_BUSY;
 332:     }
 333: 
 334:   engine->running = true;
 335: 
 336:   ret = pthread_create(&engine->thread, NULL, decision_engine_thread, engine);
 337:   if (ret != 0)
 338:     {
 339:       syslog(LOG_ERR, "[Decision] Failed to create thread: %d\n", ret);
 340:       engine->running = false;
 341:       return VELAWEAR_ERR_IO;
 342:     }
 343: 
 344:   syslog(LOG_INFO, "[Decision] Started\n");
 345:   return VELAWEAR_OK;
 346: }
 347: 
 348: int decision_engine_set_action_manager(velawear_engine_t *engine,
 349:                                         velawear_actions_t *actions)
 350: {
 351:   if (engine == NULL || actions == NULL)
 352:     {
 353:       return VELAWEAR_ERR_INVAL;
 354:     }
 355: 
 356:   pthread_mutex_lock(&engine->lock);
 357:   engine->actions = actions;
 358:   pthread_mutex_unlock(&engine->lock);
 359:   return VELAWEAR_OK;
 360: }
 361: 
 362: void decision_engine_cleanup(velawear_engine_t *engine)
 363: {
 364:   if (engine->running)
 365:     {
 366:       engine->running = false;
 367:       pthread_join(engine->thread, NULL);
 368:     }
 369: 
 370:   pthread_mutex_destroy(&engine->lock);
 371: 
 372:   syslog(LOG_INFO, "[Decision] Cleaned up\n");
 373: }
 374: 
 375: int decision_engine_add_rule(velawear_engine_t *engine,
 376:                              const char *name,
 377:                              int layer,
 378:                              uint32_t priority,
 379:                              rule_condition_t condition,
 380:                              rule_action_t action,
 381:                              void *context)
 382: {
 383:   pthread_mutex_lock(&engine->lock);
 384: 
 385:   if (engine->rule_count >= DECISION_RULES_MAX)
 386:     {
 387:       pthread_mutex_unlock(&engine->lock);
 388:       return VELAWEAR_ERR_NOMEM;
 389:     }
 390: 
 391:   decision_rule_t *rule = &engine->rules[engine->rule_count];
 392:   rule->id = engine->rule_count;
 393:   strncpy(rule->name, name, sizeof(rule->name) - 1);
 394:   rule->layer = layer;
 395:   rule->priority = priority;
 396:   rule->condition = condition;
 397:   rule->action = action;
 398:   rule->context = context;
 399:   rule->enabled = true;
 400: 
 401:   engine->rule_count++;
 402: 
 403:   pthread_mutex_unlock(&engine->lock);
 404: 
 405:   syslog(LOG_INFO, "[Decision] Added rule '%s' (layer=%d, priority=%lu)\n",
 406:          name, layer, (unsigned long)priority);
 407:   return rule->id;
 408: }
 409: 
 410: int decision_engine_remove_rule(velawear_engine_t *engine, int rule_id)
 411: {
 412:   pthread_mutex_lock(&engine->lock);
 413: 
 414:   if (rule_id < 0 || rule_id >= engine->rule_count)
 415:     {
 416:       pthread_mutex_unlock(&engine->lock);
 417:       return VELAWEAR_ERR_INVAL;
 418:     }
 419: 
 420:   engine->rules[rule_id].enabled = false;
 421: 
 422:   pthread_mutex_unlock(&engine->lock);
 423: 
 424:   syslog(LOG_INFO, "[Decision] Disabled rule %d\n", rule_id);
 425:   return VELAWEAR_OK;
 426: }
 427: 
 428: int decision_engine_evaluate(velawear_engine_t *engine,
 429:                              velawear_state_t *state,
 430:                              velawear_event_t *event)
 431: {
 432:   int ret;
 433: 
 434:   pthread_mutex_lock(&engine->lock);
 435: 
 436:   for (int i = 0; i < engine->rule_count; i++)
 437:     {
 438:       if (!engine->rules[i].enabled)
 439:         {
 440:           continue;
 441:         }
 442: 
 443:       if (engine->rules[i].condition &&
 444:           engine->rules[i].condition(state, event,
 445:                                      engine->rules[i].context))
 446:         {
 447:           ret = engine->rules[i].action(state, engine->rules[i].context);
 448:           if (ret < 0)
 449:             {
 450:               syslog(LOG_WARNING,
 451:                      "[Decision] Rule '%s' action failed: %d\n",
 452:                      engine->rules[i].name, ret);
 453:             }
 454: 
 455:           /* For emergency rules, stop after first match */
 456: 
 457:           if (engine->rules[i].layer == 0)
 458:             {
 459:               pthread_mutex_unlock(&engine->lock);
 460:               return engine->rules[i].id;
 461:             }
 462:         }
 463:     }
 464: 
 465:   pthread_mutex_unlock(&engine->lock);
 466: 
 467:   return -1;  /* No rule matched */
 468: }
