  21: 
  22: /****************************************************************************
  23:  * Private Functions
  24:  ****************************************************************************/
  25: 
  26: static void notify_callbacks(velawear_state_mgr_t *mgr)
  27: {
  28:   for (int i = 0; i < mgr->callback_count; i++)
  29:     {
  30:       if (mgr->callbacks[i])
  31:         {
  32:           mgr->callbacks[i](&mgr->state, mgr->contexts[i]);
  33:         }
  34:     }
  35: }
  36: 
  37: /****************************************************************************
  38:  * Public Functions
  39:  ****************************************************************************/
  40: 
  41: int state_manager_init(velawear_state_mgr_t *mgr)
  42: {
  43:   memset(mgr, 0, sizeof(velawear_state_mgr_t));
  44: 
  45:   pthread_mutex_init(&mgr->lock, NULL);
  46: 
  47:   /* Initialize default state */
  48: 
  49:   mgr->state.battery_level = 100;
  50:   mgr->state.is_charging = false;
  51:   mgr->state.power_mode = VELAWEAR_POWER_IDLE;
  52:   mgr->state.free_memory = 0;
  53:   mgr->state.uptime_seconds = 0;
  54:   mgr->state.is_moving = false;
  55:   mgr->state.is_running = false;
  56:   mgr->state.is_sleeping = false;
  57:   mgr->state.heart_rate = 0.0f;
  58:   mgr->state.temperature = 36.5f;
  59:   mgr->state.ble_connected = false;
  60:   mgr->state.has_network = false;
  61:   mgr->state.signal_strength = 0;
  62:   mgr->state.last_move_time = (uint32_t)time(NULL);
  63:   mgr->state.last_interaction_time = mgr->state.last_move_time;
  64:   mgr->state.fall_count_today = 0;
  65:   mgr->state.move_count_today = 0;
  66: 
  67:   syslog(LOG_INFO, "[StateMgr] Initialized\n");
  68:   return VELAWEAR_OK;
  69: }
  70: 
  71: void state_manager_cleanup(velawear_state_mgr_t *mgr)
  72: {
  73:   pthread_mutex_destroy(&mgr->lock);
  74:   syslog(LOG_INFO, "[StateMgr] Cleaned up\n");
  75: }
  76: 
  77: velawear_state_t state_manager_get_state(velawear_state_mgr_t *mgr)
  78: {
  79:   velawear_state_t state;
  80: 
  81:   pthread_mutex_lock(&mgr->lock);
  82:   memcpy(&state, &mgr->state, sizeof(velawear_state_t));
  83:   pthread_mutex_unlock(&mgr->lock);
  84: 
  85:   return state;
  86: }
