  88: void state_manager_update_battery(velawear_state_mgr_t *mgr,
  89:                                   uint32_t level, bool charging)
  90: {
  91:   pthread_mutex_lock(&mgr->lock);
  92: 
  93:   mgr->state.battery_level = level;
  94:   mgr->state.is_charging = charging;
  95: 
  96:   pthread_mutex_unlock(&mgr->lock);
  97: 
  98:   notify_callbacks(mgr);
  99: }
 100: 
 101: void state_manager_update_power_mode(velawear_state_mgr_t *mgr, int mode)
 102: {
