 111: 
 112: void state_manager_update_motion(velawear_state_mgr_t *mgr,
 113:                                  bool moving, bool running)
 114: {
 115:   pthread_mutex_lock(&mgr->lock);
 116: 
 117:   mgr->state.is_moving = moving;
 118:   mgr->state.is_running = running;
 119: 
 120:   if (moving)
 121:     {
 122:       mgr->state.last_move_time = time(NULL);
 123:       mgr->state.move_count_today++;
 124:     }
 125: 
 126:   pthread_mutex_unlock(&mgr->lock);
 127: 
 128:   notify_callbacks(mgr);
 129: }
 130: 
 131: int state_manager_update_from_event(velawear_state_mgr_t *mgr,
 132:                                      velawear_event_t *event)
 133: {
 134:   float accel_magnitude;
 135: 
 136:   if (mgr == NULL || event == NULL)
 137:     {
 138:       return VELAWEAR_ERR_INVAL;
 139:     }
 140: 
 141:   switch (event->type)
 142:     {
 143:       case VELAWEAR_EVENT_IMU_DATA:
 144:         /* IMU events carry the accelerometer sample.  Keep the state update
 145:          * in the state manager so every event follows one state boundary. */
 146:         accel_magnitude = sqrtf(event->data.imu.x * event->data.imu.x +
 147:                                 event->data.imu.y * event->data.imu.y +
 148:                                 event->data.imu.z * event->data.imu.z);
 149:         state_manager_update_motion(mgr, accel_magnitude > 0.5f,
 150:                                     accel_magnitude > 2.0f);
 151:         break;
 152: 
 153:       case VELAWEAR_EVENT_MOTION:
 154:         state_manager_update_motion(mgr,
 155:                                     event->data.motion.motion_type != 0,
 156:                                     event->data.motion.motion_type == 2);
 157:         break;
 158: 
 159:       case VELAWEAR_EVENT_FALL:
 160:         pthread_mutex_lock(&mgr->lock);
 161:         mgr->state.fall_count_today++;
 162:         pthread_mutex_unlock(&mgr->lock);
 163:         notify_callbacks(mgr);
 164:         break;
 165: 
 166:       default:
 167:         /* Events without state payload still pass through this API. */
 168:         break;
 169:     }
 170: 
 171:   return VELAWEAR_OK;
 172: }
 173: 
 174: void state_manager_update_heart_rate(velawear_state_mgr_t *mgr,
 175:                                      float heart_rate)
 176: {
 177:   pthread_mutex_lock(&mgr->lock);
 178: 
 179:   mgr->state.heart_rate = heart_rate;
 180: 
 181:   pthread_mutex_unlock(&mgr->lock);
 182: 
 183:   notify_callbacks(mgr);
 184: }
 185: 
 186: void state_manager_update_ble(velawear_state_mgr_t *mgr,
 187:                               bool connected, const char *device_name)
 188: {
 189:   pthread_mutex_lock(&mgr->lock);
 190: 
 191:   mgr->state.ble_connected = connected;
 192:   if (device_name)
 193:     {
 194:       strncpy(mgr->state.ble_device_name, device_name,
 195:               sizeof(mgr->state.ble_device_name) - 1);
 196:     }
 197: 
 198:   pthread_mutex_unlock(&mgr->lock);
 199: 
 200:   notify_callbacks(mgr);
 201: }
 202: 
 203: void state_manager_register_callback(velawear_state_mgr_t *mgr,
 204:                                      state_change_cb_t callback,
 205:                                      void *context)
 206: {
 207:   pthread_mutex_lock(&mgr->lock);
 208: 
 209:   if (mgr->callback_count < 8)
 210:     {
 211:       mgr->callbacks[mgr->callback_count] = callback;
 212:       mgr->contexts[mgr->callback_count] = context;
 213:       mgr->callback_count++;
 214:     }
 215: 
 216:   pthread_mutex_unlock(&mgr->lock);
 217: }

