 142: static bool sedentary_condition(velawear_state_t *state,
 143:                                 velawear_event_t *event,
 144:                                 void *context)
 145: {
 146:   velawear_engine_t *engine = (velawear_engine_t *)context;
 147:   uint32_t now;
 148: 
 149:   if (event == NULL || event->type != VELAWEAR_EVENT_MOTION ||
 150:       state == NULL || state->is_moving || state->last_move_time == 0)
 151:     {
 152:       return false;
 153:     }
 154: 
 155:   now = (uint32_t)time(NULL);
 156:   return now >= state->last_move_time &&
 157:          now - state->last_move_time >= sedentary_threshold_sec(engine);
 158: }
